(function(root){
const CHECKPOINT='starway-reset-checkpoint-v1',KEYS=['starway-v2','starway-best','starway-editor-v1','starway-story-maps-v1','starway-map-backups-v1','starway-restore-backup-v1','starway-story-selection-v1','starway-ghost-enabled','starway-redheat-recovery-v3','starway-redheat-override-backup-v3','starway.study.v1','starway.diagnostics.v1'];
const MAP_RECOVERY='starway-map-recovery-checkpoint-v1',MAP_KEYS=['starway-editor-v1','starway-story-maps-v1','starway-map-backups-v1','starway-restore-backup-v1','starway-redheat-recovery-v3','starway-redheat-override-backup-v3'];
function allowed(key){return KEYS.includes(key)||key.startsWith('starway-ghost-v1-');}
function capture(storage){const entries={};for(let i=0;i<storage.length;i++){const key=storage.key(i);if(allowed(key))entries[key]=storage.getItem(key);}return {format:'starway-reset-checkpoint',version:1,createdAt:new Date().toISOString(),entries};}
function validate(value){if(value?.format!=='starway-reset-checkpoint'||value.version!==1||!value.entries||typeof value.entries!=='object'||Array.isArray(value.entries)||Object.entries(value.entries).some(([key,v])=>!allowed(key)||typeof v!=='string'))throw Error('올바른 초기화 백업 파일이 아닙니다.');return value;}
function writeEntries(storage,entries){for(const [key,value]of Object.entries(entries))storage.setItem(key,value);}
function reset(storage){const snapshot=capture(storage),encoded=JSON.stringify(snapshot);const previous=storage.getItem(CHECKPOINT);if(previous&&!storage.getItem(MAP_RECOVERY)){const old=validate(JSON.parse(previous));if(MAP_KEYS.some(key=>old.entries[key]!==undefined))storage.setItem(MAP_RECOVERY,previous);}storage.setItem(CHECKPOINT,encoded);if(storage.getItem(CHECKPOINT)!==encoded)throw Error('백업을 저장하지 못했습니다.');try{for(const key of Object.keys(snapshot.entries))if(!MAP_KEYS.includes(key))storage.removeItem(key);if(Object.keys(capture(storage).entries).some(key=>!MAP_KEYS.includes(key)))throw Error('초기화 확인 실패');}catch(error){writeEntries(storage,snapshot.entries);throw error;}return snapshot;}
function restore(storage,snapshot){validate(snapshot);const current=capture(storage);try{for(const key of Object.keys(current.entries))storage.removeItem(key);writeEntries(storage,snapshot.entries);}catch(error){for(const key of Object.keys(capture(storage).entries))storage.removeItem(key);writeEntries(storage,current.entries);throw error;}}
function mapRecovery(storage){const raw=storage.getItem(MAP_RECOVERY)||storage.getItem(CHECKPOINT);return raw?validate(JSON.parse(raw)):null;}
function restoreMaps(storage,snapshot){validate(snapshot);const entries=Object.fromEntries(Object.entries(snapshot.entries).filter(([key])=>MAP_KEYS.includes(key)));if(!Object.keys(entries).length)throw Error('백업에 수정 맵이 없습니다.');const previous=Object.fromEntries(Object.keys(entries).map(key=>[key,storage.getItem(key)]));try{writeEntries(storage,entries);}catch(error){for(const [key,value]of Object.entries(previous)){if(value===null)storage.removeItem(key);else storage.setItem(key,value);}throw error;}return Object.keys(entries).length;}
root.StarwayReset={CHECKPOINT,MAP_RECOVERY,MAP_KEYS,capture,validate,reset,restore,restoreMaps,mapRecovery};
})(typeof module==='object'?module.exports:window);
